{
  "schema": "hatch.factory.conformance.telemetry_fixture.v1",
  "factory_id": "scaffolded-test",
  "target_repo": "example-org/scaffolded-test",
  "control_plane_repo": "recallnet/astrochicken",
  "harness": {
    "result_event": "factory_conformance",
    "required_summary_fields": ["result", "failed_phase"]
  },
  "benchmark_identity": {
    "required_node_attributes": ["benchmark_job_id", "prompt_version", "role_version", "skill_id"],
    "job_id_registry": "docs/contracts/benchmark-job-registry.json",
    "note": "Every LLM node (class in known set) must carry these four attributes. benchmark_job_id must be registered in the job_id_registry."
  }
}

{
  "_contract_ref": "docs/contracts/factory-public-contract.v1.json",
  "schema": "hatch.factory.config.v1",
  "factory_id": "scaffolded-test",
  "instance_id": "<FACTORY_INSTANCE_ID>",
  "target_repo": "example-org/scaffolded-test",
  "control_plane_repo": "recallnet/astrochicken",
  "factory_root": "factories/scaffolded-test",
  "tracking_issue": "<TRACKING_ISSUE_URL>",
  "trust": {
    "domain": "scaffolded-test.local",
    "roles": [
      "scaffolded-test.local.codergen",
      "scaffolded-test.local.tool",
      "scaffolded-test.local.agent.worktree",
      "scaffolded-test.local.pipeline",
      "scaffolded-test.local.fan_out.dynamic",
      "scaffolded-test.local.fan_in.dynamic"
    ]
  },
  "dispatch": {
    "graph": "factories/scaffolded-test/graphs/factory_supervisor_tick.dot"
  },
  "skills": {
    "supervisor": "packages/factory-skills/skills/runtime/supervisor_review/SKILL.md"
  },
  "scenarios": {
    "root": "factories/scaffolded-test/scenarios/scaffolded-test"
  },
  "pipeline": {
    "supervisor_tick": "factories/scaffolded-test/graphs/factory_supervisor_tick.dot"
  },
  "conformance": {
    "entrypoint": "factories/scaffolded-test/scripts/run-conformance.sh",
    "fixtures": "factories/scaffolded-test/conformance/fixtures",
    "smoke_graph": "factories/scaffolded-test/conformance/factory_supervisor_tick.dot",
    "runs_dir": ".hatch/scaffolded-test/runs"
  },
  "isolation": {
    "_note": "Factory-local isolation contract. Override auth/model/provider/runtime paths per factory; avoid implicit shared-process inheritance.",
    "auth": {
      "github": {
        "tokenEnvVar": "HATCH_FACTORY_GITHUB_TOKEN",
        "repo": "example-org/scaffolded-test",
        "factoryId": "scaffolded-test"
      }
    },
    "authStoragePath": "~/.pi/auth-<FACTORY_INSTANCE_ID>.json",
    "provider": {
      "envVar": "HATCH_MODEL_PROVIDER",
      "value": "openrouter"
    },
    "model": {
      "envVar": "HATCH_MODEL",
      "value": "openai/gpt-5.3-codex"
    },
    "paths": {
      "runs": ".hatch/scaffolded-test/runs",
      "logs": ".hatch/scaffolded-test/logs",
      "tmp": ".hatch/scaffolded-test/tmp",
      "cache": ".hatch/scaffolded-test/cache"
    }
  },
  "capabilities": {
    "goal_decomposition": {
      "timeouts": {
        "issue_draft": "30m",
        "issue_repair": "30m",
        "issue_judge": "30m",
        "issue_revise": "30m"
      }
    }
  },
  "provider": "openrouter",
  "model": "openai/gpt-5.3-codex",
  "runs_dir": ".hatch/scaffolded-test/runs",
  "canonical_checkout_path": "${HATCH_CANONICAL_CHECKOUT_PATH}",
  "policyPack": {
    "version": "v1",
    "overrides": {}
  },
  "max_concurrent_waves": 3,
  "max_goal_runs_per_tick": 2
}

digraph factory_supervisor_tick_conformance {
  start [shape=Mdiamond label="Start conformance smoke"]
  done [shape=Msquare recovery_sink_type="terminal" label="Done"]

  // This graph must remain deterministic and token-free.
  // It exists only to prove that a newly scaffolded factory can emit a real run
  // and that operator surfaces can observe it through hatch-ops.

  start -> done
}

digraph factory_supervisor_tick {
  start [shape=Mdiamond label="Start tick"]
  done [shape=Msquare recovery_sink_type="terminal" label="Done"]

  // Template contract:
  // - Any non-healable failure branch must emit a named packet before destructive cleanup.
  // - Durable, automation-consumed handoffs must use a registered packet family.
  // - Failure edges should converge to a supervisor-owned packet recovery sink with a packet ref.
  // - Template packet builders should output packet_path, packet_id, packet_type, and schema_version.
  // - Example recovery sink:
  //   recovery_wait [type="wait.human" recovery_owner="supervisor" recovery_sink_type="wait" label="Supervisor packet recovery"]

  // FREEFORM-VS-PACKET BOUNDARY
  // Allowed freeform: ephemeral agent messaging, local reasoning notes, conversational summaries not consumed by automation.
  // Must packetize: durable automation-consumed exchanges, cross-tick handoffs, ownership transfers,
  //   recovery artifacts another operator/LLM depends on, any artifact required to continue after crash/retry.

  // LLM node template — uncomment and customize when adding an LLM-calling node.
  // Required benchmark attributes (see docs/langfuse-kpis.md for field semantics):
  //   my_llm_node [class="coder"
  //                benchmark_job_id="scaffolded-test.<job_semantic_name>"
  //                prompt_version="YYYY-MM-DD.r1"
  //                role_version="1.0.0"
  //                skill_id="<skill_name>"
  //                label="..."]

  start -> done
}

{
  "_policy": "block_wait_retry",
  "_shared_note": "shared.* keys define bounded retry and cooldown defaults for blocked/waiting flows.",
  "_factory_note": "factory.* keys allow local retry budgets and wait tolerances.",
  "shared": {
    "retry": {
      "max_attempts": 3,
      "backoff_seconds": 60
    },
    "wait": {
      "cooldown_minutes": 30,
      "_cooldown_source": "DEFAULT_TERMINAL_COOLDOWN_MS in packages/factory-ops/src/commands/wave-create-ready.mjs (30 * 60 * 1000 ms = 30 minutes)"
    }
  },
  "factory": {
    "retry": {
      "max_attempts": 3,
      "backoff_seconds": 60
    },
    "wait": {
      "max_minutes": 240
    }
  }
}

{
  "_policy": "escalation",
  "_shared_note": "shared.* keys encode control-plane escalation rails required by managed-factory support.",
  "_factory_note": "factory.* keys hold local contact and retry preferences.",
  "shared": {
    "control_plane_repo": "recallnet/astrochicken",
    "issue_labels": {
      "platform_defect": "platform:defect",
      "needs_human": "needs-human"
    }
  },
  "factory": {
    "max_auto_repair_attempts": 2,
    "contacts": {
      "oncall": "factory-owner",
      "slack_channel": "#factory-ops"
    }
  }
}

{
  "_policy": "model",
  "_shared_note": "shared.* keys define cross-factory model selection and override behavior.",
  "_factory_note": "factory.* keys allow local preference tuning while preserving shared env-var override contracts.",
  "shared": {
    "default_provider": "openrouter",
    "default_model": "openai/gpt-5.3-codex",
    "override_env_vars": {
      "provider": "HATCH_MODEL_PROVIDER",
      "model": "HATCH_MODEL"
    }
  },
  "factory": {
    "provider_order": [
      "openrouter",
      "openai-codex"
    ],
    "allowed_models": [
      "openai/gpt-5.3-codex",
      "gpt-5.3-codex",
      "gpt-5.1-codex-mini",
      "gpt-5.4"
    ],
    "preferred_model": "openai/gpt-5.3-codex",
    "benchmark_justification": {
      "query_ids": [
        "cross_factory_benchmark",
        "model_comparison"
      ],
      "evidence_date": "",
      "notes": ""
    },
    "safe_fallback_model": ""
  }
}

{
  "_policy": "release",
  "_shared_note": "shared.* keys define release-channel invariants for managed factories.",
  "_factory_note": "factory.* keys are local rollout preferences and notification hooks.",
  "shared": {
    "default_channel": "stable",
    "channels": {
      "stable": {
        "required_checks": ["build", "typecheck", "test:guard-gates", "test:wave-claim-gates"]
      },
      "canary": {
        "required_checks": ["build", "typecheck"]
      },
      "pinned": {
        "required_checks": ["build", "typecheck", "test:guard-gates", "test:wave-claim-gates"]
      }
    }
  },
  "factory": {
    "preferred_channel": "stable",
    "freeze_windows": [],
    "post_merge_notifications": []
  }
}

{
  "_policy": "review",
  "_shared_note": "shared.* reviewer verdict contract must remain stable for supervisor/recovery nodes.",
  "_factory_note": "factory.* keys can be adjusted locally without breaking shared reviewer schema guarantees.",
  "shared": {
    "verdict_schema": {
      "required_fields": ["status", "summary", "findings", "qa"],
      "allowed_status": ["approve", "request_changes"]
    },
    "qa": {
      "require_command_evidence": true
    },
    "review": {
      "visual_refinement": {
        "required_metadata": [
          "visual_risk_class",
          "hotspot_files",
          "scope_limit_minutes",
          "refinement_strategy",
          "scenario_sources"
        ]
      }
    }
  },
  "factory": {
    "qa": {
      "required_command": "pnpm test",
      "visual_refinement": {
        "required_command": "npm run qa",
        "additional_evidence": [
          "scenario_root_reference",
          "agents_guidance_reference",
          "adversarial_review_artifacts"
        ]
      }
    },
    "labels": {
      "approved": "review:approved",
      "changes_requested": "review:changes-requested"
    }
  }
}

{
  "_policy": "supervisor",
  "_shared_note": "shared.* keys are platform-owned defaults and must stay aligned with control-plane runtime contracts.",
  "_factory_note": "factory.* keys are safe customization hooks. Override via factory.config.json policyPack.overrides.supervisor.",
  "shared": {
    "max_review_retries": 3,
    "review_retry_backoff_seconds": 60,
    "force_merge_on_retry_exhaustion": true,
    "dispatch": {
      "max_goal_runs_per_tick": 2
    }
  },
  "factory": {
    "max_review_retries": 2,
    "review_retry_backoff_seconds": 60,
    "dispatch": {
      "max_goal_runs_per_tick": 2
    }
  }
}

